import unicodedata as u

MARKS = {0x300, 0x301, 0x302, 0x303, 0x304, 0x306, 0x307, 0x308, 0x30a, 0x30b, 0x30c, 0x327, 0x328}
OURS = set(MARKS)
for cp in range(0xC0, 0x180):
    d = u.decomposition(chr(cp))
    if d and not d.startswith('<'):
        OURS.add(cp)

second = set()
risky = set()
for cp in range(0x110000):
    if 0xD800 <= cp < 0xE000:
        continue
    ch = chr(cp)
    d = u.decomposition(ch)
    if d and not d.startswith('<'):
        risky.add(cp)
        p = d.split()
        if len(p) == 2:
            second.add(int(p[1], 16))
    if u.combining(ch):
        risky.add(cp)
risky.update(range(0xAC00, 0xD7A4))
risky.update(second)
risky -= OURS


def merge(rs, gap):
    out = []
    for cp in sorted(rs):
        if out and cp - out[-1][1] <= gap + 1:
            out[-1][1] = cp
        else:
            out.append([cp, cp])
    return out


for gap in (0, 1, 2, 3, 4, 8, 16, 32, 64, 128, 256):
    m = merge(risky, gap)
    extra = sum(e - s + 1 for s, e in m) - len(risky)
    print(f"gap={gap:4d} ranges={len(m):4d} extra_refused={extra}")

m = merge(risky, 0)
print("non-BMP ranges:", sum(1 for s, e in m if s >= 0x10000), "bmp:", sum(1 for s, e in m if s < 0x10000))
print("risky<0x2000:", sum(1 for c in risky if c < 0x2000))
