MARKS = [0x300, 0x301, 0x302, 0x303, 0x304, 0x306, 0x307, 0x308, 0x30a, 0x30b, 0x30c, 0x327, 0x328]
OURS = {}
for cp in range(0xC0, 0x180):
    d = u.decomposition(chr(cp))
    if d and not d.startswith('<'):
        p = d.split()
        OURS[(int(p[0], 16), int(p[1], 16))] = cp

danger = {}
for cp in range(0x110000):
    if 0xD800 <= cp < 0xE000:
        continue
    d = u.decomposition(chr(cp))
    if d and not d.startswith('<'):
        p = d.split()
        if len(p) == 2:
            b = int(p[0], 16)
            m = int(p[1], 16)
            if m in MARKS and (b, m) not in OURS and u.normalize('NFC', chr(b) + chr(m)) == chr(cp):
                danger.setdefault(m, []).append(b)

A = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz#$"

def enc(n):
    s = ""
    while True:
        d = n & 31
        n >>= 5
        s += A[d + 32] if n else A[d]
        if not n:
            return s

parts = []
for m in MARKS:
    bs = sorted(danger.get(m, []))
    prev = 0
    s = ""
    for b in bs:
        s += enc(b - prev)
        prev = b
    parts.append(s)

t = "|".join(parts)
print("danger encoded chars:", len(t), "pairs:", sum(len(v) for v in danger.values()))
print("max base:", hex(max(max(v) for v in danger.values())))
```

