import json, re, glob

n = 0
hits = 0
for f in sorted(glob.glob("src/lypning/assets/*.jsonl")):
    for line in open(f):
        try:
            e = json.loads(line)
        except Exception:
            continue
        src = e.get("program") or e.get("code") or e.get("src") or e.get("source") or ""
        if not isinstance(src, str):
            continue
        if re.search(r"^\s*(import\s+random\b|from\s+random\s+import\b)", src, re.M):
            n += 1
            if "sum(" in src and re.search(r"\bseed\s*\(", src):
                hits += 1
                print(f, repr(src[:200]))
print("entries importing random:", n, "seeded+sum:", hits)

